@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--ink:#e7e5d7;--muted:#a1a99d;--gold:#dcbb73;--rust:#bb6b52;--panel:rgba(13,20,18,.91)}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101513;color:var(--ink);font-family:Manrope,system-ui,sans-serif}.game-shell{position:relative;width:100vw;height:100vh;min-height:360px;overflow:hidden;background:#17231e}canvas{display:block;width:100%;height:100%;image-rendering:pixelated;cursor:crosshair}.grain{position:absolute;inset:0;pointer-events:none;opacity:.13;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.88' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.27'/%3E%3C/svg%3E");mix-blend-mode:soft-light}.hud{position:absolute;z-index:2;top:0;left:0;right:0;height:86px;padding:20px 30px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(8,14,12,.83),transparent);pointer-events:none}.brand{display:flex;align-items:center;gap:12px}.brand-mark{font-family:serif;font-size:30px;color:var(--gold);line-height:1}.brand strong{font-size:14px;letter-spacing:.23em;display:block}.brand small{font:9px 'DM Mono',monospace;letter-spacing:.12em;color:#9aa59a}.objective{position:absolute;left:50%;transform:translateX(-50%);text-align:center;display:grid;gap:4px}.eyebrow{font:10px 'DM Mono',monospace;letter-spacing:.18em;color:#aab2a6}.objective strong{font-size:13px;font-weight:600}.hud-right{display:flex;align-items:center;gap:12px;font:11px 'DM Mono',monospace;color:#c5cabb;pointer-events:auto}.icon-button{width:32px;height:32px;border:1px solid #78807666;background:#15201dcc;color:#ddd9c8;border-radius:50%;font-size:14px;cursor:pointer}.icon-button:hover{border-color:var(--gold);color:var(--gold)}.bottom-hud{position:absolute;z-index:2;bottom:0;left:0;right:0;padding:16px 30px 19px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(0deg,rgba(8,14,12,.88),transparent);font:10px 'DM Mono',monospace;color:#bcc3b7;letter-spacing:.06em}.status{display:flex;align-items:center;gap:9px;min-width:120px}.status i{width:7px;height:7px;background:#a0b58a;border-radius:50%;box-shadow:0 0 12px #a0b58a}.status.danger i{background:#d97662;box-shadow:0 0 12px #d97662}.hint{color:#8e9b90}.hint b{color:#d8d6c6;font-weight:400}.kill-count{min-width:60px;text-align:right;color:var(--gold)}.toast{position:absolute;z-index:3;top:100px;left:50%;transform:translate(-50%,-10px);padding:10px 18px;background:rgba(13,20,18,.82);border:1px solid #bba87255;color:#e5d6b1;font:11px 'DM Mono',monospace;letter-spacing:.07em;opacity:0;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.overlay{position:absolute;z-index:5;inset:0;display:grid;place-items:center;background:rgba(7,12,10,.66);backdrop-filter:blur(5px);padding:20px;transition:opacity .35s}.overlay.hidden{opacity:0;pointer-events:none}.intro-card{width:min(590px,100%);padding:42px 46px 32px;background:var(--panel);border:1px solid #c5b07a44;box-shadow:0 24px 80px #0008;position:relative}.intro-card:before{content:"";position:absolute;left:-1px;top:25px;height:44px;width:2px;background:var(--gold)}.intro-card .eyebrow{margin:0 0 22px}.intro-card .eyebrow span{color:var(--gold)}h1{font-size:clamp(38px,6vw,61px);letter-spacing:-.06em;line-height:.98;margin:0 0 17px;font-weight:600}h1 em{font-family:Georgia,serif;font-weight:400;color:var(--gold)}.lead{color:#b6beb2;font-size:14px;line-height:1.75;max-width:430px;margin:0 0 24px}.briefing{border-top:1px solid #aeb8a122;border-bottom:1px solid #aeb8a122;padding:14px 0;margin:20px 0 23px}.briefing span{font:9px 'DM Mono',monospace;letter-spacing:.18em;color:#d9bd7a}.briefing p{color:#c6cabc;font-size:12px;line-height:1.6;margin:8px 0 0}.primary-button{background:#d3b36c;color:#17201a;border:0;padding:14px 18px;min-width:218px;font:700 10px 'DM Mono',monospace;letter-spacing:.12em;display:flex;justify-content:space-between;align-items:center;cursor:pointer;transition:transform .2s,background .2s}.primary-button:hover{background:#ebcd82;transform:translateY(-2px)}.primary-button span{font-size:17px}.control-row{display:flex;flex-wrap:wrap;gap:10px 18px;margin-top:27px;color:#8f9a8f;font:9px 'DM Mono',monospace}.control-row b{color:#d9d9cc;font-weight:500}.ending-card{border-color:#ad72634d}.ending-card .eyebrow{color:#c58470}.ending-card:before{background:#bd705b}.pause-card{width:min(450px,100%)}@media(max-width:700px){.hud{padding:15px 16px}.objective{top:68px}.bottom-hud{padding:12px 16px}.hint{display:none}.intro-card{padding:32px 27px 25px}.control-row{gap:9px}.brand small{font-size:7px}.hud-right{gap:6px}}

(()=>{
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const ui={intro:document.getElementById('intro'),ending:document.getElementById('ending'),pause:document.getElementById('pause-overlay'),objective:document.getElementById('objective'),stage:document.getElementById('stage-label'),status:document.getElementById('status-text'),statusBox:document.querySelector('.status'),kills:document.getElementById('kill-count'),toast:document.getElementById('toast'),endTitle:document.getElementById('ending-title'),endCopy:document.getElementById('ending-copy'),endStats:document.getElementById('ending-stats')};
let W=0,H=0,dpr=1,now=0,last=0,gameOn=false,paused=false,gameEnded=false,muted=false;
const world={w:1900,h:1380};
let camera={x:0,y:0,zoom:1},player,enemies=[],blood=[],particles=[],grass=[],bamboo=[],stones=[],keys={},mouse={x:0,y:0,down:false},stage=0,killTotal=0,toastTimer=0,shake=0;
const stages=[
 {name:'Atravesse o bambuzal',x:460,spawns:[['farmer',550,480],['farmer',760,650],['farmer',430,790]],message:'Os camponeses não tinham para onde fugir.'},
 {name:'A estrada foi tomada',x:1050,spawns:[['farmer',1110,390],['farmer',1260,610],['elite',1010,770]],message:'A resistência começa onde a ordem termina.'},
 {name:'Encontre o comandante',x:1550,spawns:[['elite',1510,420],['elite',1650,680]],message:'Não há reforços. Só mais uma ordem.'}
];
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
window.addEventListener('resize',resize);resize();
const rand=(a,b)=>a+Math.random()*(b-a),clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),len=(x,y)=>Math.hypot(x,y),norm=(x,y)=>{let l=len(x,y)||1;return{x:x/l,y:y/l}},dist=(a,b)=>len(a.x-b.x,a.y-b.y);
function addToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=2.5}
function startGame(){player={x:180,y:680,vx:0,vy:0,faceX:1,faceY:0,speed:210,guard:false,dash:0,dashCd:0,attack:0,attackCd:0,attackDir:{x:1,y:0},attackType:'corte',alive:true,invuln:0,moveBob:0};enemies=[];blood=[];particles=[];killTotal=0;stage=0;gameEnded=false;paused=false;gameOn=true;spawnStage(0);ui.intro.classList.add('hidden');ui.ending.classList.add('hidden');ui.pause.classList.add('hidden');ui.objective.textContent=stages[0].name;ui.stage.textContent='01 / 03';ui.kills.textContent='0 / 6';ui.status.textContent='PRONTO';ui.statusBox.classList.remove('danger');addToast('MISSÃO INICIADA');last=performance.now()}
function spawnStage(i){for(const [type,x,y] of stages[i].spawns)enemies.push(makeEnemy(type,x,y));addToast(stages[i].message)}
function makeEnemy(type,x,y){return {type,x,y,vx:0,vy:0,faceX:-1,faceY:0,state:'idle',timer:rand(.3,1),alive:true,attackDir:{x:-1,y:0},attackType:'corte',cooldown:rand(.3,1),flash:0,seed:Math.random()*10,hit:false}}
function reset(){startGame()}
document.getElementById('start-button').addEventListener('click',startGame);document.getElementById('restart-button').addEventListener('click',reset);
document.getElementById('pause-button').addEventListener('click',()=>setPause(!paused));document.getElementById('resume-button').addEventListener('click',()=>setPause(false));
document.getElementById('sound-toggle').addEventListener('click',e=>{muted=!muted;e.currentTarget.textContent=muted?'♪':'♫';addToast(muted?'ÁUDIO DESLIGADO':'ÁUDIO LIGADO')});
function setPause(v){if(!gameOn||gameEnded)return;paused=v;ui.pause.classList.toggle('hidden',!paused)}
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Escape')setPause(!paused);if(e.code==='Space'&&player)player.guard=true});window.addEventListener('keyup',e=>{keys[e.code]=false;if(e.code==='Space'&&player)player.guard=false});
canvas.addEventListener('mousemove',e=>{const r=canvas.getBoundingClientRect();mouse.x=e.clientX-r.left;mouse.y=e.clientY-r.top});canvas.addEventListener('mousedown',e=>{if(e.button===0){mouse.down=true;tryAttack()}});window.addEventListener('mouseup',()=>mouse.down=false);canvas.addEventListener('contextmenu',e=>e.preventDefault());
function screenToWorld(sx,sy){return{x:(sx-W/2)/camera.zoom+camera.x,y:(sy-H/2)/camera.zoom+camera.y}}
function tryAttack(){if(!gameOn||paused||!player?.alive||player.attackCd>0||player.dash>0)return;const target=screenToWorld(mouse.x,mouse.y),d=norm(target.x-player.x,target.y-player.y);player.faceX=d.x;player.faceY=d.y;player.attackDir=d;player.attackType=Math.abs(d.x)>.78?'corte horizontal':Math.abs(d.y)>.78?'corte vertical':'estocada';player.attack=.24;player.attackCd=.44;player.attackHit=false;spawnSlash(player.x+d.x*15,player.y+d.y*15,d.x,d.y,'#e5d6a8',7);}
function dodge(){if(!player||player.dashCd>0||player.dash>0||!player.alive)return;let x=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),y=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0);if(!x&&!y){x=player.faceX;y=player.faceY}const d=norm(x,y);player.vx=d.x*650;player.vy=d.y*650;player.dash=.18;player.dashCd=.85;player.invuln=.22;spawnBurst(player.x,player.y,'#c7ccb5',5)}
window.addEventListener('keydown',e=>{if(e.code==='ShiftLeft'||e.code==='ShiftRight')dodge()});
function spawnSlash(x,y,dx,dy,color,n=6){for(let i=0;i<n;i++)particles.push({x:x+rand(-6,6),y:y+rand(-6,6),vx:dx*rand(40,150)+rand(-50,50),vy:dy*rand(40,150)+rand(-50,50),life:rand(.14,.28),max:.28,color,size:rand(2,5)})}
function spawnBurst(x,y,color,n=8){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),s=rand(35,145);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.22,.55),max:.55,color,size:rand(2,5)})}}
function killEnemy(e,dir){e.alive=false;killTotal++;blood.push({x:e.x,y:e.y,dir,large:true});for(let i=0;i<17;i++)particles.push({x:e.x,y:e.y,vx:dir.x*rand(50,210)+rand(-100,100),vy:dir.y*rand(50,210)+rand(-100,100),life:rand(.3,.9),max:.9,color:i%3?'#8f4038':'#c26553',size:rand(2,6)});shake=Math.max(shake,7);updateKills();if(e.type==='farmer'&&killTotal===1)addToast('UM CORPO. A ORDEM NÃO MUDA.');}
function playerDeath(){if(!player.alive)return;player.alive=false;blood.push({x:player.x,y:player.y,dir:{x:-player.faceX,y:-player.faceY},large:true});shake=12;setTimeout(()=>{if(!gameOn)return;gameEnded=true;ui.endTitle.innerHTML='A ordem não<br><em>pode salvá-lo.</em>';ui.endCopy.textContent='O silêncio não distingue uniforme. Tente outra vez — ou deixe a vila em paz.';ui.endStats.textContent=`Você derrubou ${killTotal} inimigo${killTotal===1?'':'s'} antes de cair.`;document.getElementById('restart-button').innerHTML='TENTAR NOVAMENTE <span>↻</span>';ui.ending.classList.remove('hidden')},750)}
function updateKills(){const total=stages.flatMap(s=>s.spawns).length;ui.kills.textContent=`${killTotal} / ${total}`}

input.newString:
function updateKills(){const total=stages.flatMap(s=>s.spawns).length;ui.kills.textContent=`${killTotal} / ${total}`}
function initializeWorld(){let seed=391;const r=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};grass=[];bamboo=[];stones=[];for(let i=0;i<230;i++){let x=r()*world.w,y=r()*world.h;if(y<180||y>world.h-120)continue;grass.push({x,y,h:rand(8,19),phase:r()*6,color:r()})}for(let i=0;i<64;i++){let x=r()*world.w,y=120+r()*(world.h-240);if(x>200&&x<world.w-100&&Math.abs(y-690)<145)continue;bamboo.push({x,y,h:rand(65,125),w:rand(14,24),phase:r()*6,alpha:1})}for(let i=0;i<35;i++)stones.push({x:r()*world.w,y:150+r()*(world.h-300),r:rand(5,15)})}
initializeWorld();
function update(dt){if(!gameOn||paused||gameEnded)return;now+=dt;const p=player;
 p.attackCd=Math.max(0,p.attackCd-dt);p.dashCd=Math.max(0,p.dashCd-dt);p.invuln=Math.max(0,p.invuln-dt);p.attack=Math.max(0,p.attack-dt);p.moveBob+=dt*(len(p.vx,p.vy)>.1?11:2);
 const moveX=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),moveY=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0),moving=norm(moveX,moveY);
 if(p.dash>0){p.dash-=dt;if(Math.random()<.75)particles.push({x:p.x,y:p.y,vx:0,vy:0,life:.25,max:.25,color:'#c6d0bc',size:10,after:true})}else{const speed=p.speed*(p.guard?.42:1);p.vx+=(moving.x*speed-p.vx)*Math.min(1,dt*13);p.vy+=(moving.y*speed-p.vy)*Math.min(1,dt*13);if(!moveX&&!moveY){p.vx*=Math.pow(.001,dt);p.vy*=Math.pow(.001,dt)}}
 p.x=clamp(p.x+p.vx*dt,45,world.w-45);p.y=clamp(p.y+p.vy*dt,190,world.h-100);if(mouse.down&&p.attackCd<=0)tryAttack();
 if(p.attack>0&&!p.attackHit){const angle=Math.atan2(p.attackDir.y,p.attackDir.x);for(const e of enemies){if(!e.alive)continue;let dx=e.x-p.x,dy=e.y-p.y,d=len(dx,dy),delta=Math.atan2(Math.sin(Math.atan2(dy,dx)-angle),Math.cos(Math.atan2(dy,dx)-angle));if(d<76&&Math.abs(delta)<(p.attackType==='estocada'?.38:.95)){p.attackHit=true;killEnemy(e,p.attackDir);break}}}
 for(const e of enemies)updateEnemy(e,dt);
 for(const b of particles){b.life-=dt;b.x+=b.vx*dt;b.y+=b.vy*dt;b.vx*=Math.pow(.08,dt);b.vy*=Math.pow(.08,dt)}particles=particles.filter(b=>b.life>0);toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show');if(shake>0)shake=Math.max(0,shake-dt*24);
 const allDead=enemies.every(e=>!e.alive);if(allDead){if(stage<stages.length-1){const next=stages[stage+1];if(p.x>next.x-210){stage++;spawnStage(stage);ui.objective.textContent=stages[stage].name;ui.stage.textContent=`0${stage+1} / 03`;}}else if(p.x>world.w-210){finishGame()}}
 const nearest=enemies.filter(e=>e.alive).reduce((a,e)=>Math.min(a,dist(p,e)),Infinity);let targetZoom=nearest<140?.98:nearest<260?1.06:1.15;if(enemies.filter(e=>e.alive).length>1)targetZoom=.86;camera.zoom+=(targetZoom-camera.zoom)*Math.min(1,dt*2);const lookX=p.x+(mouse.x-W/2)/camera.zoom*.13,lookY=p.y+(mouse.y-H/2)/camera.zoom*.13;camera.x+=(lookX-camera.x)*Math.min(1,dt*5);camera.y+=(lookY-camera.y)*Math.min(1,dt*5);camera.x=clamp(camera.x,W/(2*camera.zoom),world.w-W/(2*camera.zoom));camera.y=clamp(camera.y,H/(2*camera.zoom),world.h-H/(2*camera.zoom));
 ui.status.textContent=p.guard?'GUARDA ATIVA':p.dash>0?'ESQUIVA':p.attack>0?'ATAQUE':nearest<120?'AMEAÇA PRÓXIMA':'PRONTO';ui.statusBox.classList.toggle('danger',nearest<120);
}
function updateEnemy(e,dt){if(!e.alive)return;e.flash=Math.max(0,e.flash-dt);e.cooldown=Math.max(0,e.cooldown-dt);e.timer-=dt;let p=player,dx=p.x-e.x,dy=p.y-e.y,d=len(dx,dy)||1;const toward={x:dx/d,y:dy/d};e.faceX=toward.x;e.faceY=toward.y;
 if(e.state==='stunned'){e.vx*=Math.pow(.05,dt);e.vy*=Math.pow(.05,dt);if(e.timer<=0)e.state='approach';}
 else if(e.state==='windup'){e.vx*=Math.pow(.01,dt);e.vy*=Math.pow(.01,dt);if(e.timer<=0){if(d<67){let direction=norm(p.x-e.x,p.y-e.y),faces=player.faceX*direction.x+player.faceY*direction.y;const inGuard=p.guard&&faces>.64;if(inGuard){const parry=p.guard&&p.attackCd<.25; if(parry){e.state='stunned';e.timer=1.05;e.vx=-direction.x*130;e.vy=-direction.y*130;spawnBurst(p.x,p.y,'#e5ca86',13);addToast('PARRY — GUARDA QUEBRADA');shake=4}else{spawnSlash(p.x,p.y,direction.x,direction.y,'#d7c58c',7);addToast('GOLPE BLOQUEADO')}}else playerDeath()}e.state='recover';e.timer=e.type==='elite'?.58:.86;e.cooldown=e.type==='elite'?1.05:1.45;}}
 else if(e.state==='recover'){if(e.timer<=0)e.state='approach'}
 else {let aggro=e.type==='farmer'?230:380;if(d<aggro&&e.cooldown<=0){e.state='windup';e.timer=e.type==='elite'?.64:.9;e.attackDir=toward;e.attackType=e.type==='elite'?'estocada':'corte';addToast(e.type==='elite'?'ESTOCADA — PREPARE A GUARDA':'ATAQUE IMINENTE — ESPELHE A DIREÇÃO');}
 else if(d>56&&d<aggro+80){let speed=e.type==='elite'?82:58;e.vx+=(toward.x*speed-e.vx)*Math.min(1,dt*4);e.vy+=(toward.y*speed-e.vy)*Math.min(1,dt*4);e.x+=e.vx*dt;e.y+=e.vy*dt}else{e.vx*=Math.pow(.05,dt);e.vy*=Math.pow(.05,dt)}}
 e.x=clamp(e.x,35,world.w-35);e.y=clamp(e.y,180,world.h-90);
}
function finishGame(){if(gameEnded)return;gameEnded=true;ui.endTitle.innerHTML='E nada<br><em>florescerá.</em>';ui.endCopy.textContent='A estrada está livre. Atrás de você, uma vila que não existe mais. A missão foi um sucesso.';ui.endStats.textContent='Relatório: território assegurado. Perdas civis: não contabilizadas.';document.getElementById('restart-button').innerHTML='VOLTAR AO INÍCIO <span>↻</span>';ui.ending.classList.remove('hidden')}

